// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 nCalls) public {
        nCalls = bound(nCalls, 1, 3);
        AirCaller caller = new AirCaller(c);
        for (uint256 i = 0; i < nCalls; i++) {
            try caller.go() {} catch {}
        }
        // The airdrop is once-only: no matter how many attempts are made,
        // a caller's balance is exactly 20 afterwards.
        assertTrue(c.tokenBalance(address(caller)) == 20);
    }
}

contract AirCaller {
    ModifierEntrancy private c;
    constructor(ModifierEntrancy _c) { c = _c; }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function go() external {
        c.airDrop();
    }
}
